import 'package:finora/domain/scan_document.dart';

/// OCR lines (text, left, top, right, bottom as fractions) that Tesseract
/// with the app's models reads from a real Дзен-мани account list
/// (1.22.1, owner's screenshot): each item is a bold name, a thin «Личное»
/// under it, a balance on the right and a round icon on the left.
List<RecognizedLine> zenLines(int psm) => [
  for (final (text, left, top, right, bottom) in psm == 3 ? _psm3 : _psm11)
    RecognizedLine(
      text: text,
      left: left,
      top: top,
      right: right,
      bottom: bottom,
      confidence: .9,
    ),
];

